files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0f0;
  --accent: #ff6b6b;
  --accent-hover: #ff5252;
  --muted: #a0a0b8;
  --border: #3a3a55;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 28px 24px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 1rem;
}

.input-row {
  display: flex;
  gap: 10px;
  margin-bottom: 6px;
}

input[type="number"] {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
  color: var(--text);
  outline: none;
  transition: border-color 0.15s;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(255, 107, 107, 0.3);
}

.hint {
  margin: 0 0 18px;
  font-size: 0.85rem;
  color: var(--muted);
}

.btn {
  font-size: 1rem;
  font-family: inherit;
  padding: 12px 20px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:active { transform: scale(0.97); }

.btn.primary {
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

.btn.primary:hover { background: var(--accent-hover); }

.btn.secondary {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--border);
  width: 100%;
  margin-top: 18px;
}

.btn.secondary:hover {
  color: var(--text);
  border-color: var(--muted);
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.stats {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.stat {
  flex: 1;
  background: var(--bg);
  border-radius: 10px;
  padding: 10px;
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 2px;
}

.stat-value {
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--accent);
}

.list-heading {
  font-size: 1rem;
  margin: 0 0 8px;
  color: var(--muted);
  font-weight: 500;
}

.readings {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 180px;
  overflow-y: auto;
}

.readings li {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  font-variant-numeric: tabular-nums;
}

.readings li:last-child { border-bottom: none; }

.empty {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
  padding: 8px 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.35rem; }
  .input-row { flex-direction: column; }
  .btn.primary { width: 100%; }
}

(function () {
  'use strict';

  var readings = [];

  var form = document.getElementById('entry-form');
  var input = document.getElementById('temp-input');
  var list = document.getElementById('readings-list');
  var emptyMsg = document.getElementById('empty-msg');
  var minEl = document.getElementById('min-val');
  var maxEl = document.getElementById('max-val');
  var avgEl = document.getElementById('avg-val');
  var clearBtn = document.getElementById('clear-btn');

  function format(n) {
    return (Math.round(n * 10) / 10).toString();
  }

  function render() {
    list.innerHTML = '';
    readings.forEach(function (t) {
      var li = document.createElement('li');
      li.textContent = format(t) + ' °C';
      list.appendChild(li);
    });

    emptyMsg.style.display = readings.length ? 'none' : 'block';

    if (!readings.length) {
      minEl.textContent = '—';
      maxEl.textContent = '—';
      avgEl.textContent = '—';
      return;
    }

    var min = Math.min.apply(null, readings);
    var max = Math.max.apply(null, readings);
    var sum = readings.reduce(function (a, b) { return a + b; }, 0);
    var avg = sum / readings.length;

    minEl.textContent = format(min) + '°';
    maxEl.textContent = format(max) + '°';
    avgEl.textContent = format(avg) + '°';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var value = parseFloat(input.value);
    if (isNaN(value)) {
      input.setCustomValidity('Please enter a valid number.');
      input.reportValidity();
      return;
    }
    if (value < -100 || value > 100) {
      input.setCustomValidity('Temperature must be between -100 and 100 °C.');
      input.reportValidity();
      return;
    }
    input.setCustomValidity('');
    readings.push(value);
    input.value = '';
    input.focus();
    render();
  });

  input.addEventListener('input', function () {
    input.setCustomValidity('');
  });

  clearBtn.addEventListener('click', function () {
    readings = [];
    render();
    input.focus();
  });

  render();
})();
